using System;
using System.IO;
using System.Text.Json;
using Baiye.Resurrection;
class Program
{
    static int passed;
    static void Main()
    {
        Test("doctor asleep before startup cannot advance",()=>{var m=Admit();Check(m.NeedsDoctor,"no exam");Check(m.Preview(10000).Seconds==0,"unexamined patient advanced");});
        Test("doctor interruption and replacement preserve exam",()=>{var m=Admit();Check(!m.DoctorWork(20),"early completion");Near(m.DoctorRemaining,40);Near(m.Preview(600).Seconds,0);Check(m.DoctorWork(40),"second doctor cannot finish");Check(m.CompleteDoctorCheck(),"authorization failed");Check(m.Stage==TreatmentStage.Rebuilding,"wrong stage");});
        Test("automatic reconstruction needs no attending doctor",()=>{var m=Building();m.Commit(m.Preview(600));Near(m.RebuildTime,600);Check(!m.NeedsDoctor,"requires doctor while running");});
        Test("first reconstruction charges precise full recipe",()=>{var m=Building();var b=m.Preview(100000);Near(b.Seconds,1800);Near(b.Metal,100);Near(b.Plastic,50);Near(b.Water,200);Near(b.Oxygen,40);m.Commit(b);Check(m.Stage==TreatmentStage.RecoveryCheck,"boundary missing");});
        Test("recovery waits for next scheduled doctor",()=>{var m=Reconstructed();Near(m.Preview(3600).Seconds,0);Near(m.RecoveryTime,0);Check(m.NeedsDoctor,"exam absent");});
        Test("doctor slept all recovery: automatic five cycles",()=>{var m=Recovering();var b=m.Preview(100000);Near(b.Seconds,3000);Near(b.Water,300);Near(b.Oxygen,60);Near(b.Nutrition,60000);m.Commit(b);Check(m.Stage==TreatmentStage.DischargeCheck,"no discharge boundary");});
        Test("discharge waits for third doctor without extra fees",()=>{var m=Recovering();m.Commit(m.Preview(3000));Near(m.Preview(600).Seconds,0);Check(Finish(m)&&m.Stage==TreatmentStage.Empty,"discharge failed");});
        Test("stockpiling cannot shorten rehabilitation",()=>{var m=Recovering();m.Commit(m.Preview(.2));Near(m.RecoveryTime,.2);Near(m.NutritionPaid,4);Check(m.Stage==TreatmentStage.Recovering,"instant completion");});
        Test("second revival costs 150 percent and same time",()=>{var m=Building(1);var b=m.Preview(1800);Near(b.Metal,150);Near(b.Plastic,75);Near(b.Water,200);Near(b.Oxygen,40);Near(b.Seconds,1800);m.Commit(b);Finish(m);Near(m.Preview(3000).Nutrition,90000);});
        Test("third revival costs 200 percent",()=>{var m=Building(2);Near(m.Preview(1800).Metal,200);Near(m.NutritionTarget,120000);});
        Test("cancel resets chamber and clears admission",()=>{var m=Building();m.Commit(m.Preview(600));m.Reset();Check(m.Stage==TreatmentStage.Empty,"not empty");Near(m.RebuildTime,0);m.Admit(1);Near(m.Multiplier,1.5);});
        Test("emergency discharge preserves both debts",()=>{var m=Recovering(1);m.Commit(m.Preview(1200));var debt=m.Debt();Check(debt.Active,"no debt");var r=new TreatmentModel();r.Resume(debt);Near(r.RecoveryTime,1200);Near(r.NutritionPaid,36000);Near(r.Multiplier,1.5);Check(r.Stage==TreatmentStage.RecoveryCheck,"no reentry exam");});
        Test("returning patient pays only remaining recovery",()=>{var m=Recovering();m.Commit(m.Preview(1200));var r=new TreatmentModel();r.Resume(m.Debt());Finish(r);var b=r.Preview(9999);Near(b.Seconds,1800);Near(b.Metal,0);Near(b.Plastic,0);Near(b.Water,180);Near(b.Oxygen,36);Near(b.Nutrition,36000);r.Commit(b);Check(r.Stage==TreatmentStage.DischargeCheck,"return not completed");});
        Test("repeated emergency admission cannot reset debt",()=>{var m=Recovering();m.Commit(m.Preview(1200));for(int i=0;i<10;i++){var r=new TreatmentModel();r.Resume(m.Debt());m=r;Finish(m);}Near(m.RecoveryTime,1200);Near(m.NutritionPaid,24000);});
        Test("pre-reconstruction cancellation cannot create recovery patient",()=>{var m=Building();m.Commit(m.Preview(1700));Check(!m.Debt().Active,"early revival exploit");Throws(()=>new TreatmentModel().Resume(m.Debt()));});
        Test("power and food pauses preserve progress",()=>{var m=Recovering();m.Commit(m.Preview(1200));var before=Snapshot(m);Near(m.RecoveryTime,1200);Check(Snapshot(m)==before,"preview mutated state");});
        Test("life support shortage rolls back time but not paid food",()=>{var m=Recovering();m.Commit(m.Preview(1200));m.LifeSupportLost(600);Near(m.RecoveryTime,1140);Near(m.NutritionPaid,24000);});
        Test("lost life support cannot create negative progress",()=>{var m=Recovering();m.LifeSupportLost(1e8);Near(m.RecoveryTime,0);Near(m.NutritionPaid,0);});
        Test("shortage during final check returns to recovery",()=>{var m=Recovering();m.Commit(m.Preview(3000));m.LifeSupportLost(600);Check(m.Stage==TreatmentStage.Recovering,"released unstable patient");Near(m.RecoveryTime,2940);Near(m.NutritionPaid,60000);var b=m.Preview(60);Near(b.Nutrition,0);m.Commit(b);Check(m.Stage==TreatmentStage.DischargeCheck,"time debt not settleable");});
        Test("reconstruction is not rolled back by recovery shortage",()=>{var m=Building();m.Commit(m.Preview(600));m.LifeSupportLost(600);Near(m.RebuildTime,600);});
        Test("replayed resource bill is rejected",()=>{var m=Building();var b=m.Preview(600);m.Commit(b);Throws(()=>m.Commit(b));Near(m.RebuildTime,600);});
        Test("forged resource bill is rejected",()=>{var m=Building();var b=m.Preview(600);b.Metal=0;Throws(()=>m.Commit(b));Near(m.RebuildTime,0);});
        Test("preview is side effect free",()=>{var m=Recovering();var before=Snapshot(m);for(int i=0;i<100;i++)m.Preview(600);Check(before==Snapshot(m),"planning advances treatment");});
        Test("invalid sim delta cannot mint progress",()=>{var m=Recovering();foreach(var dt in new[]{0,-1,double.NaN,double.PositiveInfinity}){Near(m.Preview(dt).Seconds,0);m.LifeSupportLost(dt);}Near(m.RecoveryTime,0);});
        Test("occupied admission and reentry are rejected",()=>{var m=Admit();Throws(()=>m.Admit(0));Throws(()=>m.Resume(new RecoveryDebt{Active=true}));});
        Test("negative revival count never discounts recipe",()=>{var m=Building(-5);Near(m.Multiplier,1);});
        Test("large timesteps cannot skip doctor gates",()=>{var m=Building();m.Commit(m.Preview(1e9));Check(m.Stage==TreatmentStage.RecoveryCheck,"skipped recovery examination");Near(m.RecoveryTime,0);});
        Test("200ms slices conserve eight-cycle recipe",()=>{var m=Building();double metal=0,plastic=0,water=0,oxygen=0,food=0;for(int i=0;i<24005;i++){if(m.Stage==TreatmentStage.RecoveryCheck)Finish(m);var b=m.Preview(.2);if(b.Seconds==0)break;metal+=b.Metal;plastic+=b.Plastic;water+=b.Water;oxygen+=b.Oxygen;food+=b.Nutrition;m.Commit(b);}Near(metal,100);Near(plastic,50);Near(water,500);Near(oxygen,100);Near(food,60000);Check(m.Stage==TreatmentStage.DischargeCheck,"slice completion stalled");});
        Test("final partial slice is paid without overshoot",()=>{var m=Building();m.Commit(m.Preview(1799.95));var b=m.Preview(.2);Near(b.Seconds,.05);m.Commit(b);Near(m.RebuildTime,1800);});
        Test("doctor progress snapshots round trip",()=>{var m=Admit();m.DoctorWork(27.5);var r=Restore(m);Near(r.DoctorRemaining,32.5);Check(r.Stage==TreatmentStage.StartCheck,"lost pending check");});
        Test("all treatment stages round trip",()=>{var m=Admit(2);foreach(var stage in new[]{TreatmentStage.StartCheck,TreatmentStage.Rebuilding,TreatmentStage.RecoveryCheck,TreatmentStage.Recovering,TreatmentStage.DischargeCheck}){Check(m.Stage==stage,"unexpected stage");var r=Restore(m);Check(Snapshot(r)==Snapshot(m),"state changed");if(m.NeedsDoctor)Finish(m);else m.Commit(m.Preview(10000));}});
        Test("clamped corrupted debt cannot overpay or erase time",()=>{var m=new TreatmentModel();m.Resume(new RecoveryDebt{Active=true,RecoveryTime=-100,NutritionPaid=999999,PriorRevivals=0});Near(m.RecoveryTime,0);Near(m.NutritionPaid,60000);Check(m.Stage==TreatmentStage.RecoveryCheck,"time bypass");});
        Test("unfinished doctor examination cannot authorize",()=>{var m=Admit();m.DoctorWork(59);Check(!m.CompleteDoctorCheck(),"exam shortcut");Check(m.Stage==TreatmentStage.StartCheck,"shortcut advanced stage");});
        Test("unpaid native electrical slice never advances",()=>{var m=Building();var stock=Full();Near(m.Payable(600,stock,false).Seconds,0);Near(m.RebuildTime,0);});
        Test("partial material stock cannot produce a full billed slice",()=>{var m=Building();var s=Full();s.Plastic=0;Near(m.Payable(600,s,true).Seconds,0);Near(m.RebuildTime,0);});
        Test("missing recovery nutrition blocks before debits",()=>{var m=Recovering();var s=Full();s.Nutrition=0;Near(m.Payable(600,s,true).Seconds,0);Near(m.RecoveryTime,0);Near(m.NutritionPaid,0);});
        Test("wrong gas cannot satisfy oxygen supply",()=>{var m=Recovering();var s=Full();s.Oxygen=0;Near(m.Payable(600,s,true).Seconds,0);});
        Test("actual supplied and paid slice advances once",()=>{var m=Recovering();var b=m.Payable(.2,Full(),true);Near(b.Seconds,.2);m.Commit(b);Near(m.RecoveryTime,.2);Near(m.NutritionPaid,4);});
        foreach(TreatmentStage stage in Enum.GetValues<TreatmentStage>())Test("no occupant means empty display, including reservation or stale "+stage,()=>Check(ChamberVisualState.Select(stage,false,true,false,true,false)=="idle","phantom occupant shown"));
        Test("reconstruction motion requires real paid treatment",()=>{Check(Visual(TreatmentStage.Rebuilding)=="reconstruct","no reconstruction effect");Check(Visual(TreatmentStage.Rebuilding,paid:false)=="paused","unpaid resurrection animated");Check(Visual(TreatmentStage.Rebuilding,blocked:true)=="paused","missing materials animated");});
        Test("recovery has distinct green motion and supply alarm",()=>{Check(Visual(TreatmentStage.Recovering)=="recover","wrong recovery effect");Check(Visual(TreatmentStage.Recovering,blocked:true)=="alarm","missing recovery alarm");});
        foreach(TreatmentStage stage in Enum.GetValues<TreatmentStage>())Test("power or automation off stops treatment effects "+stage,()=>Check(Visual(stage,operational:false)=="paused","motion without power"));
        foreach(var stage in new[]{TreatmentStage.StartCheck,TreatmentStage.RecoveryCheck,TreatmentStage.DischargeCheck})Test("doctor wait uses slow scan without automatic effect "+stage,()=>Check(Visual(stage)=="loaded","waiting doctor animated as treatment"));
        Test("released patient leaves no duplicate, only brief discharge effect",()=>{Check(ChamberVisualState.Select(TreatmentStage.Empty,false,true,false,false,true)=="release","no discharge effect");Check(ChamberVisualState.Select(TreatmentStage.Empty,false,true,false,false,false)=="idle","discharge never ended");Check(ChamberVisualState.Select(TreatmentStage.StartCheck,true,true,false,false,true)=="loaded","previous discharge overwrote new patient");});
        Test("empty chamber door open and fluid absent",()=>{var s=new ChamberSequence();s.Restore(new TreatmentModel());Near(s.Door,0);Near(s.Fluid,0);Check(!s.TreatmentAllowed,"empty running");});
        Test("arrival closes door before doctor and automatic work",()=>{var s=new ChamberSequence();s.Admit();Check(!s.ExamAllowed,"open exam");s.Tick(1,true);Near(s.Door,.5);s.Tick(20,false);Near(s.Door,.5);s.Tick(1,true);Check(s.ExamAllowed&&!s.TreatmentAllowed,"dry treatment");});
        Test("startup final twenty doctor seconds fill and pause",()=>{var s=Sealed();s.DoctorProgress(TreatmentStage.StartCheck,20);Near(s.Fluid,0);s.DoctorProgress(TreatmentStage.StartCheck,10);Near(s.Fluid,.5);s.Tick(600,true);Near(s.Fluid,.5);Check(!s.FinishExam(TreatmentStage.StartCheck,10),"unfinished exam");s.DoctorProgress(TreatmentStage.StartCheck,0);Check(s.FinishExam(TreatmentStage.StartCheck,0)&&s.TreatmentAllowed,"filled treatment blocked");});
        Test("final doctor drains then opens, without releasing identity",()=>{var s=Sealed();s.Fluid=1;s.DoctorProgress(TreatmentStage.DischargeCheck,10);Near(s.Fluid,.5);s.Tick(600,true);Near(s.Fluid,.5);Check(!s.BeginCarry(),"carried wet patient");Check(s.FinishExam(TreatmentStage.DischargeCheck,0),"drain failed");Near(s.Fluid,0);s.Tick(1,true);Near(s.Door,.5);Check(!s.BeginCarry(),"carried through shut door");s.Tick(1,true);Check(s.BeginCarry(),"carry missing");});
        Test("interrupted carry requeues without repeating doctor drain",()=>{var s=new ChamberSequence{Version=1,Phase=PodPhase.AwaitingCarrier};Check(s.BeginCarry(),"carry failed");s.InterruptCarry();Check(s.Phase==PodPhase.AwaitingCarrier&&s.DischargeAuthorized,"authorization lost");Near(s.Fluid,0);});
        Test("assigned carrier stays eligible after pickup, other carriers excluded",()=>{var s=new ChamberSequence{Version=1,Phase=PodPhase.AwaitingCarrier};Check(s.CarrierEligible(false),"no carrier can claim");s.BeginCarry();Check(s.CarrierEligible(true),"own pickup invalidated chore");Check(!s.CarrierEligible(false),"second carrier allowed");s.InterruptCarry();Check(s.CarrierEligible(false),"replacement carrier denied");});
        Test("door fluid mid-progress survive save and load",()=>{var s=Sealed();s.DoctorProgress(TreatmentStage.StartCheck,7);var r=JsonSerializer.Deserialize<ChamberSequence>(JsonSerializer.Serialize(s,Options),Options);r.Restore(Admit());Near(r.Fluid,.65);Near(r.Door,1);});
        Test("load during carry keeps authorized identity in chamber",()=>{var s=new ChamberSequence{Version=1,Phase=PodPhase.Carrying};s.Restore(new TreatmentModel{Stage=TreatmentStage.DischargeCheck,DoctorRemaining=0});Check(s.Phase==PodPhase.AwaitingCarrier&&s.DischargeAuthorized,"load orphaned carrier");});
        Test("0.1.1 startup migration preserves partial check and fills correctly",()=>{var m=Admit();m.DoctorWork(53);var s=new ChamberSequence();s.Restore(m);Near(s.Fluid,.65);Near(m.DoctorRemaining,7);Check(s.ExamAllowed,"migration stalled");});
        Test("0.1.1 automatic migration starts full without recipe payment",()=>{var m=Recovering();m.Commit(m.Preview(1200));var before=Snapshot(m);var s=new ChamberSequence();s.Restore(m);Check(s.TreatmentAllowed&&Snapshot(m)==before,"migration changed recipe");});
        Test("missing oxygen appears explicitly with other stock full",()=>{var m=Admit();var stock=Full();stock.Oxygen=0;Check(SupplyRequirements.Missing(stock,SupplyRequirements.Startup(m),true)=="缺少：氧气","oxygen hidden");Check(SupplyRequirements.Missing(stock,SupplyRequirements.Startup(m),false)=="Missing: oxygen","English missing");});
        Test("startup checks full scaled requirements and all shortages",()=>{var m=Admit(2);var required=SupplyRequirements.Startup(m);Near(required.Metal,200);Near(required.Plastic,100);Near(required.Nutrition,24000);Check(SupplyRequirements.Missing(new TreatmentSupplies(),required,true).Contains("氧气、水、精炼金属、塑料"),"stock missing hidden");Check(SupplyRequirements.Missing(Full(),required,true)=="","false shortage");});
        Test("food above one kg still requests refill when only 1230 kcal remains",()=>{var p=FoodSupplyPlan.Create(12000,1230,2,2,200,6000);Check(p.NeedsFood&&p.CanRequest,"mass threshold blocked nutrition");Near(p.CapacityKg,3.795);});
        Test("food reserve satisfied stops refill irrespective of small mass",()=>{var p=FoodSupplyPlan.Create(12000,12000,.5,.5,200,24000);Check(!p.NeedsFood&&!p.CanRequest,"nutrition target still fetching");Near(p.CapacityKg,.5);});
        Test("spoilage restores food demand without changing paid nutrition",()=>{var m=Recovering();m.Commit(m.Preview(120));double paid=m.NutritionPaid;var target=FoodSupplyPlan.ReserveTarget(m,true,false);Check(!FoodSupplyPlan.Create(target,target,3,3,200,6000).NeedsFood,"reserve not ready");Check(FoodSupplyPlan.Create(target,0,0,0,200,6000).CanRequest,"spoiled supply did not refill");Near(m.NutritionPaid,paid);});
        Test("clearing invalid food frees capacity without giving calories",()=>{var full=FoodSupplyPlan.Create(12000,0,0,200,200,6000);Check(full.NeedsFood&&!full.CanRequest,"overfilled invalid storage");var clear=FoodSupplyPlan.Create(12000,0,0,0,200,6000);Check(clear.CanRequest,"invalid food removal did not free delivery");Near(clear.MissingKcal,12000);});
        Test("early stages reserve startup nutrition rather than eight cycle food stock",()=>{foreach(var stage in new[]{TreatmentStage.Empty,TreatmentStage.StartCheck,TreatmentStage.Rebuilding}){var m=new TreatmentModel{Stage=stage};Near(FoodSupplyPlan.ReserveTarget(m,true,false),12000);Near(m.NutritionTarget,60000);}});
        Test("repeat revival increases nutrition buffer consistently",()=>{var m=Admit(1);Near(FoodSupplyPlan.ReserveTarget(m,true,false),18000);Near(m.NutritionTarget,90000);});
        Test("late recovery requests only unpaid nutrition",()=>{var m=Recovering();m.Commit(m.Preview(2950));Near(FoodSupplyPlan.ReserveTarget(m,true,false),1000);Near(m.NutritionTarget,60000);});
        Test("paid nutrition and time only debt never hoard food",()=>{var m=Recovering();m.Commit(m.Preview(3000));m.LifeSupportLost(60);Near(FoodSupplyPlan.ReserveTarget(m,true,false),0);});
        Test("empty or authorized discharge does not refill",()=>{Near(FoodSupplyPlan.ReserveTarget(Admit(),false,false),0);Near(FoodSupplyPlan.ReserveTarget(Admit(),true,true),0);var m=Recovering();m.Commit(m.Preview(3000));Near(FoodSupplyPlan.ReserveTarget(m,true,false),0);});
        Test("unknown food source offers small retryable native batch",()=>{var p=FoodSupplyPlan.Create(12000,0,0,0,200,0);Check(p.CanRequest,"no task for a future printed food");Near(p.CapacityKg,1);});
        Test("delivery respects storage space and bounded mass batch",()=>{var p=FoodSupplyPlan.Create(12000,0,19,19,20,1);Near(p.CapacityKg,20);var huge=FoodSupplyPlan.Create(12000,0,0,0,2000000,1);Near(huge.CapacityKg,200);});
        Test("invalid stock inputs never generate infinite delivery amount",()=>{var p=FoodSupplyPlan.Create(12000,double.NaN,double.NaN,0,200,double.NaN);Check(p.CanRequest,"invalid stock suppressed retry");Near(p.CapacityKg,1);Check(!FoodSupplyPlan.Create(double.PositiveInfinity,0,0,0,200,1).CanRequest,"infinite demand");});
        Console.WriteLine(passed+" treatment and visual behavior scenarios passed");
    }
    static TreatmentModel Admit(int prior=0){var m=new TreatmentModel();m.Admit(prior);return m;}
    static ChamberSequence Sealed(){var s=new ChamberSequence();s.Admit();s.Tick(2,true);return s;}
    static string Visual(TreatmentStage stage,bool operational=true,bool blocked=false,bool paid=true)=>ChamberVisualState.Select(stage,true,operational,blocked,paid,false);
    static TreatmentModel Building(int prior=0){var m=Admit(prior);m.DoctorWork(60);m.CompleteDoctorCheck();return m;}
    static TreatmentModel Reconstructed(int prior=0){var m=Building(prior);m.Commit(m.Preview(1800));return m;}
    static TreatmentModel Recovering(int prior=0){var m=Reconstructed(prior);m.DoctorWork(60);m.CompleteDoctorCheck();return m;}
    static bool Finish(TreatmentModel m){m.DoctorWork(m.DoctorRemaining);return m.CompleteDoctorCheck();}
    static TreatmentSupplies Full()=>new TreatmentSupplies{Metal=1e6,Plastic=1e6,Water=1e6,Oxygen=1e6,Nutrition=1e9};
    static readonly JsonSerializerOptions Options=new JsonSerializerOptions{IncludeFields=true};
    static string Snapshot(TreatmentModel m)=>JsonSerializer.Serialize(m,Options);
    static TreatmentModel Restore(TreatmentModel m)=>JsonSerializer.Deserialize<TreatmentModel>(Snapshot(m),Options);
    static void Test(string name,Action action){action();passed++;Console.WriteLine("PASS "+name);}
    static void Near(double a,double b){Check(Math.Abs(a-b)<1e-5,$"Expected {b}, got {a}");}
    static void Throws(Action a){try{a();}catch(InvalidOperationException){return;}throw new Exception("Expected rejection");}
    static void Check(bool ok, string message) { if(!ok) throw new Exception(message); }
}
